yp=yq;
zp=zq;

//rotate on y axis again
axs2 = sin(time*0.4)*3.3;
xq=xp*cos(axs2) - zp*sin(axs2);
zq=xp*sin(axs2) + zp*cos(axs2);
xp=xq;
zp=zq;

//stretch y axis to compensate for aspect ratio
yp=yp*1.2;

//add orbit value
xp=xp+t2;
zp=zp+t3;
yp=yp+t4;

//push forward into viewpace
zp=zp+2.1;

//project x,y,z into screenspace
xs=xp/zp;
ys=yp/zp;

//center 0,0 in middle of screen
x=xs+0.5;
y=ys+0.5;

r=(value1+0.5)*0.1;
g=(value1+0.5)*0.2;
b=(value1+0.5)*1.0;

n=sample*6.283;
ang=int(sample*12)/12 * 6.283;
ps=time*0.1;

//circle;
xp=sin(n*12+ps)*0.5;
yp=cos(n*12+ps)*0.5;
zp=2 + q1*0.03;

//positions on y axis
xq=xp*sin(ang) + zp*cos(ang);
yq=yp;
zq=xp*cos(ang) - zp*sin(ang);

//rotate on x;
xp=xq;
yp=yq*sin(q2) + zq*cos(q2);
zp=yq*cos(q2) - zq*sin(q2);

//rotate on z;
xq=xp*sin(q2) + yp*cos(q2);
yq=xp*cos(q2) - yp*sin(q2);
zq=zp;


xp=xq;
yp=yq;
zp=zq;

zp=zp+8;
xs=xp/zp;
ys=yp/zp;

x=xs+0.5;
y=ys*1.3+0.5;

n=sample*6.283;

flip=flip+1;
flip=flip*below(flip,2);

phase=sin(n*3)*sin(n*7.9)*sin(n*16.7)*sin(n*63.5)*6;

xp=sin(n+phase)*flip;
yp=cos(n+phase)*flip;
zp=0;

//rotate on y during draw
ang=n*2+phase*0.2;
xq=xp*sin(ang) + zp*cos(ang);
yq=yp;
zq=xp*cos(ang) - zp*sin(ang);

r1=0.1;g1=0.6;b1=1;
r2=1.0;g2=0.7;b2=0.1;
fade=xq*0.5 + 0.5;
r=r1*fade + r2*(1-fade);
g=g1*fade + g2*(1-fade);
b=b1*fade + b2*(1-fade);

//rotation;
ang=time*0.1;
xp=xq*sin(ang) + zq*cos(ang);
yp=yq;
zp=xq*cos(ang) - zq*sin(ang);

ang=time*0.17;
xq=xp;
yq=yp*sin(ang) + zp*cos(ang);
zq=yp*cos(ang) - zp*sin(ang);


//push into viewspace
zq=zq+3.1;


//project into screenspace
xs=xq/zq;
ys=yq/zq;


x=xs+0.5;
y=ys*1.3+0.5;
a=(1-flip)*0.03*q1;

